## ---- 01: Loading and Inspecting Treasury Data  (qmd line 242) ------------------------

library(dnsr)
library(dplyr)
library(ggplot2)

# Pull a Treasury yield panel from FRED via dnsr
yields <- get_treasury_yield_data(api_key = NULL,
                                   start_date = "2010-01-01")
# Or the combined panel across all maturities
# (wide format: Date plus one column per maturity, in years)
yields_combined <- get_treasury_yield_combined(start_date = "2010-01-01")
head(yields_combined)

# Snapshot one date for cross-sectional fitting
snap <- yields_combined %>% filter(Date == max(Date))
mats <- as.numeric(setdiff(names(snap), "Date"))
curve_df <- data.frame(
  maturity = mats,
  yield    = as.numeric(snap[, setdiff(names(snap), "Date")])
)
ggplot(curve_df, aes(maturity, yield)) +
  geom_line() +
  geom_point() +
  labs(x = "Maturity (yrs)", y = "Yield",
       title = "U.S. Treasury Curve") +
  theme_minimal()


## ---- 02: Bootstrapping a Zero Curve  (qmd line 272) ----------------------------------

# Helper: bootstrap zero curve from par yields (didactic — not in package)
bootstrap_zero <- function(par_yields, maturities, dt = 0.5) {
  n <- length(maturities)
  P <- numeric(n)
  for (k in seq_len(n)) {
    coupon <- par_yields[k] * dt
    if (k == 1) {
      P[k] <- 1 / (1 + coupon)
    } else {
      pv_coupons <- sum(coupon * P[1:(k-1)])
      P[k] <- (1 - pv_coupons) / (1 + coupon)
    }
  }
  z <- -log(P) / maturities
  data.frame(maturity = maturities, par = par_yields, zero = z)
}

bootstrap_zero(par_yields = c(0.045, 0.046, 0.047, 0.048, 0.050),
               maturities = c(0.5, 1.0, 1.5, 2.0, 2.5))


## ---- 03: Quick Pipeline Sketch  (qmd line 296) ---------------------------------------

# A minimal four-stage pipeline call using real package functions
library(dnsr); library(oasr)

# Stage 1: calibrate the DNS model to recent Treasury data (dnsr),
# then simulate rate paths in the format the oasr analytics consume
# A multi-year window: factor dynamics (mean-reversion speeds) cannot be
# identified from short samples, and are estimated on month-end factors.
# `lambda` holds the Nelson-Siegel decay rate fixed across the window, so
# the factor series is measured against one set of loadings (Chapter 5)
calib <- get_calibrated_dns_params(lookback_days = 1250,
                                    lambda = ns_lambda(3.5))
rates <- simulate_rates(
  calib, n_paths = 500, n_periods = 360,
  maturities = c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30)
)

# Stage 2: project credit vectors (oasr)
asset_data <- oasr::sample_abs_data   # bundled sample pool
prepay     <- prepayment_model(type = "cpr_cdr",
                                base_cpr = 0.06, base_cdr = 0.01)
credit_v   <- calculate_credit_vectors(asset_data, rates, prepay)

# Stage 3: cashflow projection (oasr)
ref_rates <- extract_reference_rates(rates, reference_key = "10")
cf <- project_cashflows(asset_data, credit_v,
                         reference_rates = ref_rates)

# Stage 4: NPV / OAS (oasr)
pv <- calculate_present_value(cf, rates, oas = 120)  # OAS in bps


